fn find_median(a: &[i32], b: &[i32]) -> i32 {
    let n = a.len();
    // We assume `n == b.len()` and `n > 0` per problem statement.

    if n % 2 == 1 {
        // Odd length: return the middle element of `a`.
        a[n / 2]
    } else {
        // Even length: average the last element of the lower half of `a`
        // (index n/2 - 1) and the first element of `b` (index 0), using
        // floor division for negative sums.
        let x = a[n / 2 - 1] as i64;
        let y = b[0] as i64;
        let sum = x + y;
        // Rust’s `/` rounds toward zero. We want floor division when sum < 0.
        let avg = if sum >= 0 || sum % 2 == 0 {
            sum / 2
        } else {
            // sum < 0 and odd, so subtract 1 to round down
            sum / 2 - 1
        };
        avg as i32
    }
}

